import { ArrowDownToLine, ArrowLeft, ArrowUpRight, Archive, Bell, Brain, FolderGit2, CalendarDays, Check, CheckCheck, ChevronDown, ChevronRight, Circle, CircleCheck, Clock3, Code2, Columns3, Command, Database, Download, File, FileText, Folder, FolderOpen, HardDrive, ImagePlus, Layers3, Loader2, Menu, MessageSquare, MoreHorizontal, PanelLeftClose, PanelLeftOpen, Paperclip, Pencil, Pin, Plus, RefreshCw, Search, Send, Settings2, ShieldCheck, ShoppingCart, Sparkles, Sun, Target, Trash2, Upload, WandSparkles, X, Zap } from 'lucide-react';
import type { Connections, Conversation, Doc, Generation, Goal, Page, Source, Workspace } from './types';
