import { api, getConnections, getSources, setAccessToken } from './lib/api';
import { favoritesOf, toggleFavorite } from './lib/favorites';
// The two composers are Chat's alone and carry framer-motion and file handling, so they load when Chat
// first renders rather than sitting in the app's cold start.
const Compose = lazy(() => import('@/components/ui/compose').then(m => ({ default: m.Compose })));
const ClaudeChatInput = lazy(() => import('@/components/ui/claude-chat-input').then(m => ({ default: m.ClaudeChatInput })));
import { Markdown } from './Markdown';
import { Skills, type InstalledSkill } from './Skills';
import { Today } from './Today';
import { Projects, type ProjectsData } from './Projects';
import { MonthCalendar } from './MonthCalendar';
import { Kanban } from './Kanban';
import { BuyList } from './BuyList';
