type Update = (workspace: Workspace) => Workspace;
type Commit = (update: Update, message?: string) => Promise<boolean>;
type Confirm = { title: string; description: string; action: () => Promise<unknown>; label?: string; danger?: boolean };
type Editor = { doc: Doc; fresh: boolean };
// Projects has no row: Today links to it. Files and Generate are gone as pages (Andrew's decision of
// 2026-09-24): notes still live in workspace.docs, reached from search and Pinned, and Generate is a
// mode of Chat.
const navigation: { id: Page; label: string; icon: typeof Brain; hint?: string }[] = [
  // Kanban is one page for the board, todos, goals and the buy list. Network is not a tab (Andrew, 2026-09-25:
  // "it looks ugly as a tab"); the map is reached from the home globe, and #network still opens it.
  // Projects stays a row under Today and a command in the topbar search, not a tab (the restructure decision agenda.test records).
  { id: 'agenda', label: 'Today', icon: CalendarDays }, { id: 'board', label: 'Kanban', icon: Columns3 }, { id: 'skills', label: 'Skills', icon: Zap }, { id: 'chat', label: 'andliu.ai', icon: MessageSquare },
  // Added 2026-09-28: writing and drawing each get a row, since each is a place he works in. The resume
  // moved under Docs the same day (Andrew: "combine that as a setting under notes"), a note of kind
  // Resume; #resume still opens it as a page, for bookmarks.
  { id: 'docs', label: 'Docs', icon: FileText }, { id: 'draw', label: 'Whiteboard', icon: Pencil }, { id: 'pdf', label: 'PDF tools', icon: Layers3 },
];
// The pages the address can name. 'files' and 'generate' are not here on purpose: #files and #generate
// fall through to the home page, the same as any unknown hash.
const labels: Partial<Record<Page, string>> = { today: 'Home', agenda: 'Today', projects: 'Projects', calendar: 'Calendar', board: 'Kanban', buy: 'Buy', network: 'Network', skills: 'Skills', goals: 'Goals', chat: 'andliu.ai', settings: 'Settings', docs: 'Docs', draw: 'Whiteboard', resume: 'Resume', write: 'Writing', pdf: 'PDF tools' };
// The welcome note is a notification, not a file (Andrew, 2026-09-25). Read state lives in this browser.
const WELCOME = { id: 'welcome', title: 'Welcome to my second brain', body: 'Capture a thought with the plus, keep the day on Today, the work on Kanban, and ask andliu.ai anything about where things are. Everything is saved in this browser; Settings exports a backup.' };
const READ_KEY = 'brain-notifications-read';
const readNotifications = (): string[] => { try { return JSON.parse(localStorage.getItem(READ_KEY) || '[]'); } catch { return []; } };
// The sidebar folds to an icon rail (Andrew, 2026-09-28) from its button or Ctrl B; the choice lives in this browser.
const COLLAPSED_KEY = 'brain-sidebar-collapsed';
const readCollapsed = () => { try { return localStorage.getItem(COLLAPSED_KEY) === '1'; } catch { return false; } };
// Ctrl B is bold in a text field, so it only folds the sidebar when the key is not going into one.
const typing = (target: EventTarget | null) => target instanceof Element && !!target.closest('input, textarea, select, [contenteditable]:not([contenteditable="false"])');
const providerNames: Record<string, string> = { claude: 'Claude', openai: 'OpenAI', gemini: 'Gemini', kie: 'Kie.ai', fal: 'fal.ai' };
// Claude defaults to Opus 5 (Andrew, 2026-09-28; the API reference lists no "5.5"). The Claude ids here are the
// current ones from that reference; OpenAI and Gemini keep whatever the server is configured with.
const defaultModels: Record<string, string> = { claude: 'claude-opus-5', openai: 'gpt-5.4', gemini: 'gemini-3.5-flash' };
const knownModelIds: Record<string, string[]> = { claude: ['claude-opus-5', 'claude-opus-4-8', 'claude-sonnet-5', 'claude-haiku-4-5'] };
const formatDate = (value: string) => new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
const bytes = (value = 0) => value > 1048576 ? `${(value / 1048576).toFixed(1)} MB` : value > 1024 ? `${Math.round(value / 1024)} KB` : `${value} B`;
const excerpt = (text: string, length = 140) => text.replace(/^#+\s/gm, '').replace(/[\n\r]+/g, ' ').slice(0, length);
const isText = (doc: Doc) => doc.kind !== 'file' || !doc.data || /^(text\/|application\/(json|xml|javascript))/.test(doc.mime || '') || /\.(md|txt|csv|json|yaml|yml|ts|tsx|js|jsx|py|css|html|xml|log)$/i.test(doc.name);
const documentIcon = (doc: Doc) => doc.mime?.startsWith('image/') ? ImagePlus : FileText;
function withActivity(w: Workspace, text: string, page: Page): Workspace { return { ...w, activity: [activity(text, page), ...w.activity].slice(0, 100) }; }
// The address is #<page>, or #skills/<rest> for one skill's pop-up (see Skills.tsx), or #projects/<rest>
// for one project's page (see Projects.tsx), or #calendar/<day> for the full month on one day, or #write/<docId>
// for one note full screen (see Write.tsx). A folder name with a space arrives percent-encoded.
// No hash at all, and #today, is the home page (Home.tsx, the workspace as a globe), the cold open, so
// browser Back to the bare address returns there. The old Today page is #agenda, "Today" in the nav.
function readHash() { let hash = location.hash.slice(1) || 'today'; try { hash = decodeURIComponent(hash); } catch { /* keep it as typed */ } const [base, ...rest] = hash.split('/'); return base in labels ? { page: base as Page, path: base === 'skills' || base === 'projects' || base === 'network' || base === 'calendar' || base === 'write' ? rest.join('/') : '' } : null; }
function IconButton({ label, children, onClick, className = '', disabled = false }: { label: string; children: ReactNode; onClick: () => void; className?: string; disabled?: boolean }) { return <button type="button" className={`icon-button ${className}`} aria-label={label} title={label} onClick={onClick} disabled={disabled}>{children}</button>; }
function Empty({ icon: Icon = FolderOpen, title, children, action }: { icon?: typeof Brain; title: string; children: ReactNode; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon"><Icon size={24}/></div><h3>{title}</h3><p>{children}</p>{action}</div>; }
function Modal({ title, children, close, wide = false }: { title: string; children: ReactNode; close: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDialogElement>(null);
  // React's autoFocus runs while the dialog is still closed, so showModal() then focuses its first button, the Close X.
  // Every modal with a text field autofocuses its first one, so the caret goes back there.
  useEffect(() => { const dialog = ref.current!; const previous = document.activeElement as HTMLElement | null; dialog.showModal(); dialog.querySelector<HTMLElement>('input:not([type=checkbox]), textarea')?.focus(); return () => { dialog.close(); previous?.focus(); }; }, []);
  return <dialog ref={ref} className={`modal ${wide ? 'modal-wide' : ''}`} aria-label={title} onCancel={event => { event.preventDefault(); close(); }} onClick={event => { if (event.target === ref.current) close(); }}><header className="modal-header"><h2>{title}</h2><IconButton label="Close dialog" onClick={close}><X size={18}/></IconButton></header>{children}</dialog>;
}
// A page header is the title and the page's primary action, nothing else.
// level 2 when the block sits inside another page (Goals on the Kanban page), so a page has one h1.
function PageHeading({ title, children, level = 1 }: { title: string; children?: ReactNode; level?: 1 | 2 }) { const H = level === 1 ? 'h1' : 'h2'; return <div className="page-heading"><div><H>{title}</H></div>{children && <div className="heading-actions">{children}</div>}</div>; }

export default function App() {
  const [workspace, setWorkspace] = useState<Workspace | null>(null);
  const current = useRef<Workspace | null>(null); const queue = useRef(Promise.resolve());
  const [loadError, setLoadError] = useState(''); const [saving, setSaving] = useState(0);
  const [page, setPage] = useState<Page>(() => readHash()?.page || 'today'); const [subPath, setSubPath] = useState(() => readHash()?.path || '');
  const [installed, setInstalled] = useState<InstalledSkill[] | null>(null); const [skillsError, setSkillsError] = useState(''); const [liveContext, setLiveContext] = useState<Doc[]>([]);
  const [projects, setProjects] = useState<ProjectsData | null>(null); const [projectsError, setProjectsError] = useState('');
  const [menuOpen, setMenuOpen] = useState(false); const [collapsed, setCollapsed] = useState(readCollapsed); const [toast, setToast] = useState<{ text: string; error: boolean } | null>(null);
  const [connections, setConnections] = useState<Connections | null>(null); const [connectionError, setConnectionError] = useState(''); const [checking, setChecking] = useState(false);
  const [editor, setEditor] = useState<Editor | null>(null); const [preview, setPreview] = useState<Doc | null>(null); const [confirm, setConfirm] = useState<Confirm | null>(null);
  const [searchOpen, setSearchOpen] = useState(false); const [search, setSearch] = useState(''); const [mapHits, setMapHits] = useState(0);
  const [sourcesOpen, setSourcesOpen] = useState(false); const [attached, setAttached] = useState<string[]>([]); const [activeChat, setActiveChat] = useState<string | null>(null);
  const [chatMode, setChatMode] = useState<'chat' | 'generate'>('chat');
  const [ask, setAsk] = useState('');
  const [notifOpen, setNotifOpen] = useState(false); const [read, setRead] = useState<string[]>(readNotifications);
  const notifications = [WELCOME]; const unread = notifications.filter(n => !read.includes(n.id));
  const markRead = (id: string) => { const next = [...read, id]; setRead(next); try { localStorage.setItem(READ_KEY, JSON.stringify(next)); } catch { /* read for this visit only */ } };
  const importRef = useRef<HTMLInputElement>(null);
  const notify = (text: string, error = false) => setToast({ text, error });
  const commit: Commit = (update, message) => new Promise(resolve => {
    setSaving(count => count + 1);
    queue.current = queue.current.then(async () => { try { if (!current.current) throw new Error('Workspace is still loading.'); const next = update(current.current); await saveWorkspace(next); current.current = next; setWorkspace(next); if (message) notify(message); resolve(true); } catch (error) { notify(`Could not save: ${error instanceof Error ? error.message : 'Storage unavailable'}`, true); resolve(false); } finally { setSaving(count => count - 1); } });
  });
  async function connect() { setChecking(true); setConnectionError(''); try { setConnections(await getConnections()); } catch (error) { setConnections(null); setConnectionError(error instanceof Error ? error.message : 'Connection unavailable'); } finally { setChecking(false); } }
  async function load() { setLoadError(''); try { const data = await loadWorkspace(); current.current = data; setWorkspace(data); } catch (error) { setLoadError(error instanceof Error ? error.message : 'Could not open browser storage'); } }
  // Installed skills are read from disk on each visit to Skills, so a skill installed a minute ago shows up.
  async function loadSkills() { try { const reply = await api<{ skills?: InstalledSkill[] }>('skills'); setInstalled(Array.isArray(reply.skills) ? reply.skills : []); setSkillsError(''); } catch (error) { setInstalled(list => list || []); setSkillsError(error instanceof Error ? error.message : 'Could not read installed skills'); } }
  // Repos, courses and Blueberry's STATUS.md, read fresh on each visit to Today or Projects. A reply without them (an
  // older server, a test) reads as empty lists, never as a crash.
  async function loadProjects() { try { const reply = await api<Partial<ProjectsData>>('projects'); setProjects({ repos: reply.repos || [], courses: reply.courses || [], blueberry: reply.blueberry || null, rootPath: reply.rootPath }); setProjectsError(''); } catch (error) { setProjectsError(error instanceof Error ? error.message : 'Could not read projects'); } }
  useEffect(() => { void load(); void connect(); }, []);
  useEffect(() => { if (page === 'skills' || installed === null) void loadSkills(); if (page === 'agenda' || page === 'projects') void loadProjects(); }, [page]);
  // Every move to another page, or to another project inside one, starts at the top of it. Opening or closing
  // a skill's pop-up does not: the grid or list stays where it was scrolled to, under the pop-up.
  const shownPage = useRef(page);
  useEffect(() => { if (page !== 'skills' || shownPage.current !== 'skills') document.documentElement.scrollTop = 0; shownPage.current = page; }, [page, subPath]);
  useEffect(() => { try { localStorage.setItem(COLLAPSED_KEY, collapsed ? '1' : '0'); } catch { /* folded for this visit only */ } }, [collapsed]);
  useEffect(() => { if (!toast) return; const timeout = setTimeout(() => setToast(null), toast.error ? 10000 : 4500); return () => clearTimeout(timeout); }, [toast]);
  useEffect(() => { const onHash = () => { const next = readHash(); if (next) { setPage(next.page); setSubPath(next.path); } }; const onKey = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key === 'k') { event.preventDefault(); setSearchOpen(value => !value); } if (event.ctrlKey && event.key.toLowerCase() === 'b' && !typing(event.target)) { event.preventDefault(); setCollapsed(value => !value); } }; window.addEventListener('hashchange', onHash); window.addEventListener('keydown', onKey); return () => { window.removeEventListener('hashchange', onHash); window.removeEventListener('keydown', onKey); }; }, []);
  function navigate(next: Page, path = '') { setPage(next); setSubPath(path); location.hash = path ? next + '/' + path : next; setMenuOpen(false); }
  // A skill written in the browser opens in the Skills pop-up, like an installed one, wherever it is clicked.
  const openDoc = (doc: Doc) => { if (doc.kind !== 'skill') return setPreview(doc); setPage('skills'); setSubPath('personal/' + doc.id); location.hash = 'skills/personal/' + doc.id; };
  // Use in Chat for an installed skill: its SKILL.md goes to Chat as context held in memory, never saved as a copy.
  const chatWithSkill = (skill: InstalledSkill) => { const doc = { ...makeDoc(skill.name, skill.skill, 'skill'), id: 'installed:' + skill.slug }; setLiveContext(docs => [...docs.filter(item => item.id !== doc.id), doc]); setAttached(ids => ids.includes(doc.id) ? ids : [...ids, doc.id]); navigate('chat'); notify(`${skill.name} attached to Chat`); };
  const duplicateSkill = (skill: InstalledSkill) => setEditor({ doc: { ...makeDoc(skill.name, skill.skill, 'skill'), source: `~/.claude/skills/${skill.path}/SKILL.md` }, fresh: true });
  function newDoc(kind: Doc['kind'] = 'note') { setEditor({ doc: makeDoc('', '', kind), fresh: true }); }
  // Quick capture on Today: the first line of the thought becomes the note's title.
  function captureNote(text: string) { const doc = makeDoc(text.split('\n')[0].slice(0, 80), text, 'note', ['Quick capture']); return commit(w => withActivity({ ...w, docs: [doc, ...w.docs] }, `Captured ${doc.name}`, 'files'), 'Thought captured'); }
  async function saveDoc(doc: Doc, fresh: boolean) { const next = { ...doc, updated: now() }; const ok = await commit(w => withActivity({ ...w, docs: fresh ? [next, ...w.docs] : w.docs.map(item => item.id === doc.id ? next : item) }, `${fresh ? 'Created' : 'Updated'} ${doc.name}`, doc.kind === 'skill' ? 'skills' : 'files'), fresh ? 'Added to your workspace' : 'Changes saved'); if (ok) { setEditor(null); if (preview?.id === doc.id) setPreview(next); } return ok; }
  async function importFiles(files: FileList | null) { if (!files?.length) return; try { const docs = await Promise.all(Array.from(files).map(async file => { if (file.size > 20 * 1024 * 1024) throw new Error(`${file.name} exceeds the 20 MB file limit.`); const doc = { ...makeDoc(file.name, '', 'file'), mime: file.type || 'application/octet-stream', size: file.size, data: await readData(file) }; if (isText(doc)) doc.content = await file.text(); return doc; })); await commit(w => withActivity({ ...w, docs: [...docs, ...w.docs] }, `Imported ${docs.length} ${docs.length === 1 ? 'file' : 'files'}`, 'files'), `${docs.length} ${docs.length === 1 ? 'file' : 'files'} imported`); } catch (error) { notify(error instanceof Error ? error.message : 'Import failed', true); } if (importRef.current) importRef.current.value = ''; }
  const pinDoc = (doc: Doc) => { void commit(w => ({ ...w, docs: w.docs.map(item => item.id === doc.id ? { ...item, pinned: !item.pinned, updated: now() } : item) }), doc.pinned ? 'Unpinned from Today' : 'Pinned to Today'); if (preview?.id === doc.id) setPreview({ ...doc, pinned: !doc.pinned }); };
  const deleteDoc = (doc: Doc) => setConfirm({ title: `Delete “${doc.name}”?`, description: 'This removes the saved copy and its file bytes from this browser. Your original source file is unaffected. Export a backup first if you need to recover it.', action: async () => { const ok = await commit(w => withActivity({ ...w, docs: w.docs.filter(item => item.id !== doc.id), relations: (w.relations || []).filter(e => e.source !== 'doc:' + doc.id && e.target !== 'doc:' + doc.id) }, `Deleted ${doc.name}`, 'files'), 'Removed from your workspace'); if (ok) { setPreview(null); setAttached(ids => ids.filter(id => id !== doc.id)); if (doc.kind === 'skill') navigate('skills'); } }, danger: true, label: 'Delete permanently' });
  const attachDoc = (doc: Doc) => { setAttached(ids => ids.includes(doc.id) ? ids : [...ids, doc.id]); setPreview(null); navigate('chat'); notify(`${doc.name} attached to Chat`); };
  const exportDoc = (doc: Doc) => download(doc.kind === 'note' || doc.kind === 'skill' ? `${doc.name.replace(/\.md$/, '')}.md` : doc.name, doc.data || new Blob([doc.content], { type: doc.mime || 'text/markdown' }));
  if (!workspace) return <div className="boot-screen"><div className="brand-icon"><Brain size={27}/></div><h1>Second Brain</h1>{loadError ? <><p className="error-text">{loadError}</p><button className="button" onClick={() => void load()}>Retry opening workspace</button></> : <><Loader2 className="spin" size={20}/><p>Opening your workspace…</p></>}</div>;
  const skills = workspace.docs.filter(doc => doc.kind === 'skill');
  const searchText = search.trim().toLowerCase();
  // The topbar search lists what can be done from anywhere: go to a page, capture, run the two upkeep skills,
  // or fall through to a workspace search with the typed text (Ctrl K still opens that search directly).
  const commands: SearchAction[] = [
    ...navigation.map(({ id, label, icon: Icon }) => ({ id: 'go:' + id, label, icon: <Icon size={14}/>, end: 'Page' })),
    { id: 'go:projects', label: 'Projects', icon: <FolderGit2 size={14}/>, end: 'Page' }, { id: 'go:settings', label: 'Settings', icon: <Settings2 size={14}/>, end: 'Page' }, { id: 'go:network', label: 'Network map', icon: <Layers3 size={14}/>, end: 'Page' },
    { id: 'capture', label: 'Capture a thought', icon: <Plus size={14}/>, description: 'new note', end: 'Action' },
    { id: 'run:clean-up', label: 'Clean up', icon: <Zap size={14}/>, description: 'stray processes and temp files', end: 'Run' },
    { id: 'run:doctor-plus', label: 'Doctor plus', icon: <Zap size={14}/>, description: 'health check, changes nothing', end: 'Run' },
    { id: 'search', label: 'Search everything', icon: <Search size={14}/>, short: 'Ctrl K', end: 'Search' },
  ];
  async function runCommand(id: string) {
    if (id.startsWith('go:')) return navigate(id.slice(3) as Page);
    if (id === 'capture') return newDoc();
    if (id === 'search') return setSearchOpen(true);
    if (id.startsWith('run:')) { const task = id.slice(4); try { await api('run', { id: task }); notify(`${task === 'clean-up' ? 'Clean up' : 'Doctor plus'} started; output is on Skills`); } catch (error) { notify(error instanceof Error ? error.message : 'Could not start the run', true); } }
  }
  const toastView = toast && <div className={`toast ${toast.error ? 'toast-error' : ''}`} role={toast.error ? 'alert' : 'status'}>{toast.error ? <Circle size={17}/> : <CircleCheck size={17}/>}<span>{toast.text}</span><IconButton label="Dismiss notification" onClick={() => setToast(null)}><X size={15}/></IconButton></div>;
  // The write page (#write/<docId>) is one note and nothing else, so it replaces the shell rather than
  // hiding parts of it the way the home page does: no sidebar, top bar, modals or timer are mounted at all.
  // Only the toast stays, because a failed save is reported there. Keyed on the id so another note starts fresh.
  if (page === 'write') return <><Suspense fallback={<div className="boot-screen"><Loader2 className="spin"/><p>Opening the note…</p></div>}><Write key={subPath} workspace={workspace} commit={commit} id={subPath}/></Suspense>{toastView}</>;
  return <div className={`app-shell ${page === 'today' ? 'app-home' : ''} ${collapsed ? 'sidebar-collapsed' : ''}`}>
    <a className="skip-link" href="#main-content">Skip to content</a>
    {menuOpen && <button aria-label="Close navigation" className="sidebar-scrim" onClick={() => setMenuOpen(false)}/>}
    <aside className={`sidebar ${menuOpen ? 'sidebar-open' : ''}`} aria-label="Workspace navigation">
      <button className="brand" title={collapsed ? 'Second Brain' : undefined} onClick={() => navigate('today')}><span className="brand-icon"><Brain size={22}/></span><span><strong>Second Brain<span className="brand-dot">.</span></strong></span></button>
      <div className="nav-label">WORKSPACE</div>
      <nav>{navigation.map(({ id, label, icon: Icon }) => <button key={id} className={`nav-item ${page === id ? 'active' : ''}`} aria-current={page === id ? 'page' : undefined} title={collapsed ? label : undefined} onClick={() => navigate(id)}><Icon size={18}/><span>{label}</span>{id === 'skills' && <small>{(installed?.length || 0) + skills.length}</small>}{id === 'chat' && <span className="nav-ai">AI</span>}</button>)}</nav>
      <div className="sidebar-bottom"><button className={`nav-item ${page === 'settings' ? 'active' : ''}`} onClick={() => navigate('settings')} aria-current={page === 'settings' ? 'page' : undefined} title={collapsed ? 'Settings' : undefined}><Settings2 size={18}/><span>Settings</span></button><button type="button" className="nav-item sidebar-toggle" aria-expanded={!collapsed} title={`${collapsed ? 'Expand' : 'Collapse'} sidebar (Ctrl B)`} onClick={() => setCollapsed(value => !value)}>{collapsed ? <PanelLeftOpen size={18}/> : <PanelLeftClose size={18}/>}<span>{collapsed ? 'Expand sidebar' : 'Collapse sidebar'}</span></button><div className="profile"><span className="profile-avatar">Y</span><span><strong>Your space</strong><small>Local storage</small></span><span className="status-dot"/></div></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumbs"><IconButton label="Open navigation" className="menu-button" onClick={() => setMenuOpen(true)}><Menu size={20}/></IconButton><span className="breadcrumb-root">Workspace</span><ChevronRight size={13}/><strong>{labels[page]}</strong><span className="local-badge"><span className="status-dot"/>Local</span></div><div className="topbar-actions"><span className="save-status">{saving ? <><Loader2 size={12} className="spin"/> Saving…</> : <><CheckCheck size={13}/> Saved on device</>}</span><ActionSearchbar className="topbar-search" actions={commands} onSelect={action => void runCommand(action.id)} onSubmit={query => { setSearch(query); setSearchOpen(true); }}/>
      <FocusTimer/><ThemeButton/><div className="notifications" onKeyDown={event => { if (event.key === 'Escape' && notifOpen) { event.stopPropagation(); setNotifOpen(false); } }}><IconButton label={unread.length ? `Notifications, ${unread.length} unread` : 'Notifications'} className={`notif-button ${unread.length ? 'has-unread' : ''}`} onClick={() => setNotifOpen(v => !v)}><Bell size={17}/>{unread.length > 0 && <span className="notif-ping" aria-hidden="true"/>}</IconButton>
        {notifOpen && <div className="notif-panel panel" role="dialog" aria-label="Notifications">
          {notifications.map(n => <article key={n.id} className="notif-item" data-unread={!read.includes(n.id) || undefined}><h3>{n.title}</h3><p>{n.body}</p>{!read.includes(n.id) && <button type="button" className="text-button" onClick={() => markRead(n.id)}>Mark as read</button>}</article>)}
          <button type="button" className="icon-button notif-close" aria-label="Close notifications" onClick={() => setNotifOpen(false)}><X size={14}/></button>
        </div>}
      </div></div></header>
      {unread[0] && !notifOpen && <div className="notif-banner" role="note" aria-label="Unread notification"><Bell size={14}/><strong>{unread[0].title}</strong><span>{unread[0].body}</span><button type="button" className="text-button" onClick={() => markRead(unread[0].id)}>Got it</button></div>}
      <main id="main-content" className={`main-content page-${page}`} tabIndex={-1}>
        {page === 'network' && <Suspense fallback={<div className="panel boot-screen"><Loader2 className="spin"/><p>Opening your network…</p></div>}><Network notify={notify} path={subPath}/></Suspense>}
        {page === 'today' && <Suspense fallback={<div className="panel boot-screen"><Loader2 className="spin"/><p>Opening your workspace…</p></div>}><Home notify={notify} openMenu={() => setMenuOpen(true)} openSearch={() => setSearchOpen(true)} newDoc={() => newDoc()}/></Suspense>}
        {page === 'agenda' && <Today data={projects} error={projectsError} workspace={workspace} commit={commit} openDoc={openDoc} newDoc={() => newDoc()} capture={captureNote}/>}
        {/* The full month, reached from Today's calendar card; #calendar/<day> opens on that day. Keyed on the day so a new one starts fresh. */}
        {page === 'calendar' && <><a className="text-button project-back" href="#agenda"><ArrowLeft size={15}/>Today</a><PageHeading title="Calendar"/><MonthCalendar key={subPath} focus={subPath} todos={workspace.todos}/></>}
        {page === 'projects' && <Projects path={subPath} data={projects} error={projectsError} refresh={() => { setProjects(null); void loadProjects(); }} workspace={workspace} commit={commit}/>}
        {page === 'board' && <div className="bento kanban-bento">
          <section className="bento-cell bento-wide"><Kanban workspace={workspace} commit={commit}/></section>
          <section className="bento-cell"><TodoCard workspace={workspace} commit={commit}/></section>
          <section className="bento-cell"><BuyList workspace={workspace} commit={commit}/></section>
          <section className="bento-cell bento-wide"><MiscList workspace={workspace} commit={commit}/></section>
          <section className="bento-cell bento-wide"><Goals workspace={workspace} commit={commit} confirm={setConfirm} level={2}/></section>
        </div>}
        {page === 'buy' && <><PageHeading title="Buy"/><BuyList workspace={workspace} commit={commit}/></>}
        {page === 'docs' && <Suspense fallback={<div className="panel boot-screen"><Loader2 className="spin"/><p>Opening your documents…</p></div>}><Docs workspace={workspace} commit={commit} remove={deleteDoc}/></Suspense>}
        {page === 'draw' && <><PageHeading title="Whiteboard"/><Whiteboard workspace={workspace} commit={commit}/></>}
        {page === 'pdf' && <Suspense fallback={<div className="panel boot-screen"><Loader2 className="spin"/><p>Opening PDF tools…</p></div>}><PdfTools workspace={workspace} commit={commit}/></Suspense>}
        {page === 'resume' && <><PageHeading title="Resume"/><Resume workspace={workspace} commit={commit}/></>}
        {page === 'skills' &&<Skills path={subPath} installed={installed} error={skillsError} personal={skills} newSkill={() => newDoc('skill')} chat={chatWithSkill} duplicate={duplicateSkill} mine={{ attach: attachDoc, edit: doc => setEditor({ doc, fresh: false }), pin: pinDoc, download: exportDoc, remove: deleteDoc }} favorites={favoritesOf(workspace).skills} toggleFavorite={key => void commit(w => toggleFavorite(w, 'skills', key))} review={favoritesOf(workspace).review} toggleReview={key => void commit(w => toggleFavorite(w, 'review', key))}/>}
        {page === 'goals' && <Goals workspace={workspace} commit={commit} confirm={setConfirm}/>}
        {page === 'chat' && <>
          <div className="tabs page-modes" role="group" aria-label="Chat mode">{(['chat', 'generate'] as const).map(mode => <button key={mode} type="button" className={chatMode === mode ? 'selected' : ''} aria-pressed={chatMode === mode} onClick={() => setChatMode(mode)}>{mode === 'chat' ? <><MessageSquare size={14}/>Chat</> : <><WandSparkles size={14}/>Generate</>}</button>)}</div>
          {chatMode === 'chat' ? <Chat workspace={workspace} commit={commit} connections={connections} liveContext={liveContext} attached={attached} setAttached={setAttached} activeId={activeChat} setActiveId={setActiveChat} navigate={navigate} notify={notify} confirm={setConfirm} installed={installed || []} attachSkill={chatWithSkill} initialPrompt={ask} clearInitialPrompt={() => setAsk('')}/>
            : <Generate workspace={workspace} commit={commit} connections={connections} navigate={navigate} notify={notify} confirm={setConfirm}/>}
        </>}
        {page === 'settings' && <Settings workspace={workspace} commit={commit} connections={connections} error={connectionError} checking={checking} refresh={connect} confirm={setConfirm} notify={notify}/>}
      </main>
    </div>
    <input ref={importRef} type="file" multiple className="sr-only" aria-label="Import files" onChange={event => void importFiles(event.target.files)}/>
    {editor && <EditorModal editor={editor} close={() => setEditor(null)} save={saveDoc}/>}
    {preview && <Modal title="File details" close={() => setPreview(null)} wide><div className="preview-meta"><div className={`doc-symbol ${preview.kind}`} >{(() => { const Icon = documentIcon(preview); return <Icon size={25}/>; })()}</div><div><h2>{preview.name}</h2><p>{preview.kind === 'note' ? 'Note' : preview.mime || 'File'} · Updated {formatDate(preview.updated)} {preview.size ? `· ${bytes(preview.size)}` : ''}</p></div></div><div className="preview-toolbar"><button className={`button small ${preview.pinned ? 'copper-text' : ''}`} onClick={() => pinDoc(preview)}><Pin size={14}/>{preview.pinned ? 'Unpin' : 'Pin'}</button>{isText(preview) && <button className="button small" onClick={() => { setEditor({ doc: preview, fresh: false }); setPreview(null); }}><Pencil size={14}/>Edit</button>}<button className="button small" onClick={() => exportDoc(preview)}><Download size={14}/>Download</button>{isText(preview) && <button className="button small" onClick={() => attachDoc(preview)}><MessageSquare size={14}/>Use in Chat</button>}<IconButton label="Delete saved copy" onClick={() => deleteDoc(preview)} className="danger-text"><Trash2 size={15}/></IconButton></div><div className="preview-content">{preview.data && preview.mime?.startsWith('image/') ? <img className="file-image" src={preview.data} alt={preview.name}/> : preview.data && preview.mime === 'application/pdf' ? <><iframe title={preview.name} className="pdf-preview" src={preview.data}/><p className="muted">If your browser does not display this PDF, use Download above.</p></> : isText(preview) ? <Markdown content={preview.content || 'This file is empty.'}/> : <Empty icon={File} title="Your original file is safely stored">Download this file to open it in its native application.</Empty>}</div>{preview.tags.length > 0 && <div className="preview-tags">{preview.tags.map(tag => <span className="tag" key={tag}>{tag}</span>)}</div>}{preview.source && <div className="source-path"><Folder size={13}/><span>Copied from {preview.source}</span></div>}</Modal>}
    {confirm && <ConfirmModal value={confirm} close={() => setConfirm(null)}/>}
    {sourcesOpen && <SourcesModal close={() => setSourcesOpen(false)} commit={commit} openDoc={setPreview} notify={notify} navigate={navigate}/>}
    {searchOpen && <Modal title="Search your workspace" close={() => { setSearchOpen(false); setSearch(''); }} wide><div className="global-search"><Search size={20}/><input aria-label="Search files, goals and conversations" autoFocus placeholder="Find a file on this computer, a note, skill, goal, or conversation…" value={search} onChange={event => setSearch(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') { event.preventDefault(); document.querySelector<HTMLButtonElement>('.search-results .search-result')?.dispatchEvent(new MouseEvent('click', { bubbles: true, ctrlKey: event.ctrlKey || event.metaKey, shiftKey: event.shiftKey })); } }}/></div><div className="search-results">{!searchText ? <Empty icon={Search} title="Everything, within reach">Every file under the map's roots on this computer, plus the titles, content, and tags of your saved workspace. Enter opens the first result; Ctrl+Enter also opens a file on this computer, Shift+Enter reveals it in Explorer.</Empty> : <><MapSearch query={searchText} onCount={setMapHits} onPick={(id, name, action) => { setSearchOpen(false); setSearch(''); navigate('network', id); if (action) void api<{ runnable?: boolean }>('graph/open', { id, reveal: action === 'reveal' }).then(reply => notify(reply.runnable ? `${name} is a script, so it was revealed in Explorer rather than run` : action === 'reveal' ? `Revealed ${name} in Explorer` : `Opened ${name} on this computer`)).catch(error => notify(error instanceof Error ? error.message : 'Could not open the file', true)); }}/>{workspace.docs.filter(doc => `${doc.name} ${doc.content} ${doc.tags.join(' ')}`.toLowerCase().includes(searchText)).slice(0, 20).map(doc => <button className="search-result" key={doc.id} onClick={() => { setSearchOpen(false); openDoc(doc); }}><FileText size={18}/><span><strong>{doc.name}</strong><small>{doc.kind} · {excerpt(doc.content, 80)}</small></span><ArrowUpRight size={15}/></button>)}{workspace.goals.filter(goal => `${goal.title} ${goal.description}`.toLowerCase().includes(searchText)).map(goal => <button className="search-result" key={goal.id} onClick={() => { setSearchOpen(false); navigate('goals'); }}><Target size={18}/><span><strong>{goal.title}</strong><small>Goal · {goal.category}</small></span><ArrowUpRight size={15}/></button>)}{workspace.conversations.filter(chat => `${chat.title} ${chat.messages.map(message => message.content).join(' ')}`.toLowerCase().includes(searchText)).map(chat => <button className="search-result" key={chat.id} onClick={() => { setSearchOpen(false); setActiveChat(chat.id); navigate('chat'); }}><MessageSquare size={18}/><span><strong>{chat.title}</strong><small>Conversation · {chat.messages.length} messages</small></span><ArrowUpRight size={15}/></button>)}{!mapHits && !workspace.docs.some(doc => `${doc.name} ${doc.content} ${doc.tags.join(' ')}`.toLowerCase().includes(searchText)) && !workspace.goals.some(goal => `${goal.title} ${goal.description}`.toLowerCase().includes(searchText)) && !workspace.conversations.some(chat => `${chat.title} ${chat.messages.map(message => message.content).join(' ')}`.toLowerCase().includes(searchText)) && <Empty icon={Search} title="No matches yet">Try another word or a shorter search.</Empty>}</>}</div></Modal>}
    {toastView}
  </div>;
}

function EditorModal({ editor, close, save }: { editor: Editor; close: () => void; save: (doc: Doc, fresh: boolean) => Promise<boolean> }) {
  const [name, setName] = useState(editor.doc.name); const [content, setContent] = useState(editor.doc.content); const [tags, setTags] = useState(editor.doc.tags.join(', ')); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [discard, setDiscard] = useState(false);
  const dirty = name !== editor.doc.name || content !== editor.doc.content || tags !== editor.doc.tags.join(', ');
  function requestClose() { if (dirty) setDiscard(true); else close(); }
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!name.trim()) { setError('Give this a title before saving.'); return; } setBusy(true); const changedContent = content !== editor.doc.content; await save({ ...editor.doc, name: name.trim(), content, tags: [...new Set(tags.split(',').map(tag => tag.trim()).filter(Boolean))], ...(changedContent && editor.doc.data ? { data: await readData(new Blob([content], { type: editor.doc.mime || 'text/plain' })), size: new Blob([content]).size } : {}) }, editor.fresh); setBusy(false); }
  return <Modal title={`${editor.fresh ? 'New' : 'Edit'} ${editor.doc.kind === 'skill' ? 'skill' : editor.doc.kind === 'note' ? 'note' : 'text file'}`} close={requestClose} wide><form onSubmit={event => void submit(event)} className="editor-form"><label>Title<input autoFocus value={name} onChange={event => setName(event.target.value)} placeholder={editor.doc.kind === 'skill' ? 'e.g. Thoughtful writing partner' : 'Give your idea a name'} required maxLength={200}/></label><label>{editor.doc.kind === 'skill' ? 'Instructions' : 'Content'}<textarea className="editor-textarea" value={content} onChange={event => setContent(event.target.value)} placeholder={editor.doc.kind === 'skill' ? 'Describe the expertise, approach, and instructions the AI should follow…' : 'Start writing. Markdown headings and lists are welcome.'}/></label><label>Tags<span className="field-hint">Separate with commas</span><input value={tags} onChange={event => setTags(event.target.value)} placeholder="Ideas, Personal, Research" maxLength={500}/></label>{error && <p className="error-text" role="alert">{error}</p>}{discard && <div className="inline-confirm"><span>You have unsaved changes.</span><button type="button" className="text-button danger-text" onClick={close}>Discard changes</button><button type="button" className="text-button" onClick={() => setDiscard(false)}>Keep editing</button></div>}<div className="modal-footer"><span className="muted"><HardDrive size={13}/>Saved on this device</span><button type="button" className="button" onClick={requestClose}>Cancel</button><button className="button primary" disabled={busy || !name.trim()}>{busy ? <Loader2 className="spin" size={15}/> : <Check size={15}/>}Save {editor.doc.kind === 'skill' ? 'skill' : 'note'}</button></div></form></Modal>;
}

function ConfirmModal({ value, close }: { value: Confirm; close: () => void }) { const [busy, setBusy] = useState(false); return <Modal title={value.title} close={() => { if (!busy) close(); }}><div className="confirm-body"><div className={`empty-icon ${value.danger ? 'danger-text' : ''}`}>{value.danger ? <Trash2 size={22}/> : <Database size={22}/>}</div><p>{value.description}</p></div><div className="modal-footer"><button className="button" onClick={close} disabled={busy}>Cancel</button><button className={`button ${value.danger ? 'danger' : 'primary'}`} disabled={busy} onClick={async () => { setBusy(true); try { await value.action(); close(); } finally { setBusy(false); } }}>{busy && <Loader2 className="spin" size={15}/>} {value.label || 'Confirm'}</button></div></Modal>; }

function SourcesModal({ close, commit, openDoc, notify, navigate }: { close: () => void; commit: Commit; openDoc: (doc: Doc) => void; notify: (text: string, error?: boolean) => void; navigate: (page: Page) => void }) {
  const [sources, setSources] = useState<Source[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [query, setQuery] = useState(''); const [source, setSource] = useState<(Doc & { sourceId: string }) | null>(null); const [opening, setOpening] = useState(''); const [saving, setSaving] = useState(false);
  async function refresh() { setLoading(true); setError(''); try { setSources((await getSources()).sources); } catch (error) { setError(error instanceof Error ? error.message : 'Could not read local library'); } finally { setLoading(false); } }
  useEffect(() => { void refresh(); }, []);
  async function inspect(item: Source) { setOpening(item.id); setError(''); try { const data = await api<{ name: string; content: string; mime: string; data?: string; kind: 'file'; path: string; updated: string }>('source', { id: item.id }); setSource({ ...makeDoc(data.name, data.content, data.kind), mime: data.mime, data: data.data, size: item.size, source: data.path, sourceId: item.id }); } catch (error) { setError(error instanceof Error ? error.message : 'Could not read source'); } finally { setOpening(''); } }
  async function saveCopy() { if (!source || saving) return; setSaving(true); const { sourceId: _sourceId, ...doc } = source; const copy = { ...doc, id: uid(), created: now(), updated: now() }; if (await commit(w => withActivity({ ...w, docs: [copy, ...w.docs] }, `Imported ${copy.name} from local library`, 'files'))) { notify('Personal copy saved. Your source stays unchanged.'); close(); openDoc(copy); } setSaving(false); }
  const filtered = sources.filter(item => `${item.name} ${item.path}`.toLowerCase().includes(query.toLowerCase()));
  return <Modal title="Connected local library" close={close} wide>{source ? <><div className="source-detail"><button className="text-button" onClick={() => setSource(null)}>← Back to library</button><h2>{source.name}</h2><p className="source-path">{source.source}</p><div className="source-readonly"><ShieldCheck size={14}/>Source preview · Save a personal copy to edit or use in Chat</div>{source.data && source.mime?.startsWith('image/') ? <img src={source.data} alt={source.name} className="file-image"/> : source.data && source.mime === 'application/pdf' ? <iframe src={source.data} title={source.name} className="pdf-preview"/> : source.content ? <Markdown content={source.content}/> : <Empty icon={File} title="Original file ready to import">Save a copy to retain the file bytes in your workspace.</Empty>}</div><div className="modal-footer"><button className="button" onClick={() => setSource(null)}>Back</button><button className="button primary" disabled={saving} onClick={() => void saveCopy()}>{saving ? <Loader2 className="spin" size={15}/> : <Plus size={15}/>}Save personal copy</button></div></> : <><div className="source-intro"><p>Read files from the folders connected to your local server. Saving a copy brings the content into this browser.</p><label className="inline-search"><Search size={16}/><input autoFocus aria-label="Search local library" value={query} onChange={event => setQuery(event.target.value)} placeholder="Search connected files…"/></label></div>{error && <div className="error-banner" role="alert"><p>{error}</p><button className="button small" onClick={() => void refresh()}><RefreshCw size={14}/>Retry</button><button className="text-button" onClick={() => { close(); navigate('settings'); }}>Connection settings <ArrowUpRight size={14}/></button></div>}<div className="source-list">{loading ? <div className="loading-state"><Loader2 size={23} className="spin"/><p>Reading your local library…</p></div> : filtered.length ? filtered.map(item => <button className="source-item" key={item.id} disabled={!!opening} onClick={() => void inspect(item)}><span className="doc-symbol file"><FileText size={19}/></span><span><strong>{item.name}</strong><small>{item.path}</small></span><span className="source-size">{bytes(item.size)}</span>{opening === item.id ? <Loader2 size={16} className="spin"/> : <ChevronRight size={16}/>}</button>) : !error && <Empty icon={FolderOpen} title={query ? 'No matching sources' : 'No sources found'}>{query ? 'Try a different name or folder.' : 'Configure your local library folders in the server environment, then refresh. Settings includes the setup details.'}</Empty>}</div><div className="modal-footer"><span className="muted">{sources.length} files found</span><button className="button" onClick={() => void refresh()} disabled={loading}><RefreshCw size={14}/>Refresh library</button></div></>}</Modal>;
}

function Goals({ workspace, commit, confirm, level = 1 }: { workspace: Workspace; commit: Commit; confirm: (value: Confirm) => void; level?: 1 | 2 }) {
  const [showArchived, setShowArchived] = useState(false); const [editing, setEditing] = useState<Goal | null>(null); const [fresh, setFresh] = useState(false);
  const goals = workspace.goals.filter(goal => goal.archived === showArchived); const total = goals.reduce((sum, goal) => sum + goal.milestones.length, 0); const done = goals.reduce((sum, goal) => sum + goal.milestones.filter(item => item.done).length, 0);
  const create = () => { setFresh(true); setEditing({ id: uid(), title: '', description: '', category: 'Personal', due: '', archived: false, milestones: [], created: now() }); };
  function toggle(goal: Goal, milestoneId: string) { void commit(w => ({ ...w, goals: w.goals.map(item => item.id === goal.id ? { ...item, milestones: item.milestones.map(milestone => milestone.id === milestoneId ? { ...milestone, done: !milestone.done } : milestone) } : item) })); }
  function archive(goal: Goal) { void commit(w => withActivity({ ...w, goals: w.goals.map(item => item.id === goal.id ? { ...item, archived: !item.archived } : item) }, `${goal.archived ? 'Restored' : 'Archived'} goal: ${goal.title}`, 'goals'), goal.archived ? 'Goal restored' : 'Goal archived'); }
  return <><PageHeading title="Goals" level={level}><button className="button primary" onClick={create}><Plus size={16}/>New goal</button></PageHeading><div className="goal-summary"><div><span className="summary-icon"><Target size={23}/></span><span><strong>{workspace.goals.filter(goal => !goal.archived).length}</strong><small>Active goals</small></span></div><div><span className="summary-icon green-text"><CircleCheck size={23}/></span><span><strong>{done}<span className="summary-total"> / {total}</span></strong><small>Milestones completed {showArchived ? 'in archive' : ''}</small></span></div><p>Progress is a practice.<br/><span>Make the next step a small one.</span></p></div><div className="library-toolbar"><div className="tabs"><button className={!showArchived ? 'selected' : ''} onClick={() => setShowArchived(false)}>Active<span>{workspace.goals.filter(goal => !goal.archived).length}</span></button><button className={showArchived ? 'selected' : ''} onClick={() => setShowArchived(true)}><Archive size={14}/>Archived<span>{workspace.goals.filter(goal => goal.archived).length}</span></button></div></div>{goals.length ? <div className="goals-grid">{goals.map(goal => { const count = goal.milestones.filter(item => item.done).length; const progress = goal.milestones.length ? Math.round(count / goal.milestones.length * 100) : 0; const overdue = goal.due && new Date(goal.due + 'T23:59:59') < new Date() && progress < 100; return <article className="goal-card panel" key={goal.id}><div className="goal-card-top"><span className="tag">{goal.category || 'Personal'}</span><div><IconButton label={`Edit ${goal.title}`} onClick={() => { setFresh(false); setEditing(goal); }}><Pencil size={14}/></IconButton><IconButton label={goal.archived ? `Restore ${goal.title}` : `Archive ${goal.title}`} onClick={() => archive(goal)}><Archive size={14}/></IconButton><IconButton label={`Delete ${goal.title}`} onClick={() => confirm({ title: 'Delete this goal?', description: `“${goal.title}” and all its milestones will be permanently removed from this browser.`, danger: true, label: 'Delete goal', action: () => commit(w => withActivity({ ...w, goals: w.goals.filter(item => item.id !== goal.id), relations: (w.relations || []).filter(e => e.source !== 'goal:' + goal.id && e.target !== 'goal:' + goal.id) }, `Deleted goal: ${goal.title}`, 'goals'), 'Goal deleted') })}><Trash2 size={14}/></IconButton></div></div><h2>{goal.title}</h2><p>{goal.description || 'A little progress, every day.'}</p><div className="goal-progress-label"><span>{count} of {goal.milestones.length} milestones</span><strong>{progress}%</strong></div><div className="progress-track"><span style={{ width: `${progress}%` }}/></div><div className="milestone-list">{goal.milestones.length ? goal.milestones.map(item => <label className={`milestone ${item.done ? 'done' : ''}`} key={item.id}><input type="checkbox" checked={item.done} onChange={() => toggle(goal, item.id)}/><span>{item.title}</span></label>) : <button className="text-button" onClick={() => { setFresh(false); setEditing(goal); }}><Plus size={14}/>Break this goal into milestones</button>}</div><div className={`goal-card-footer ${overdue ? 'copper-text' : ''}`}><Clock3 size={13}/>{goal.due ? `${overdue ? 'Overdue · ' : 'Due '}${formatDate(goal.due + 'T12:00:00')}` : 'No deadline set'}{progress === 100 && goal.milestones.length > 0 && <span className="green-text"><CheckCheck size={14}/>All milestones complete</span>}</div></article>; })}</div> : <div className="panel"><Empty icon={Target} title={showArchived ? 'A place for completed chapters.' : 'What do you want to move toward?'} action={!showArchived && <button className="button primary" onClick={create}><Plus size={16}/>Create your first goal</button>}>{showArchived ? 'Archived goals will stay here, along with their milestones.' : 'A project, a habit, a bigger ambition. Name it, add a few milestones, and give yourself a place to start.'}</Empty></div>}{editing && <GoalEditor goal={editing} fresh={fresh} close={() => setEditing(null)} save={async goal => { const ok = await commit(w => withActivity({ ...w, goals: fresh ? [goal, ...w.goals] : w.goals.map(item => item.id === goal.id ? goal : item) }, `${fresh ? 'Created' : 'Updated'} goal: ${goal.title}`, 'goals'), fresh ? 'Goal created' : 'Goal updated'); if (ok) setEditing(null); }}/>}</>;
}

function GoalEditor({ goal, fresh, close, save }: { goal: Goal; fresh: boolean; close: () => void; save: (goal: Goal) => Promise<void> }) { const [value, setValue] = useState(goal); const [milestone, setMilestone] = useState(''); const [busy, setBusy] = useState(false); const [discard, setDiscard] = useState(false); const dirty = JSON.stringify(value) !== JSON.stringify(goal) || !!milestone; function requestClose() { if (dirty) setDiscard(true); else close(); } function add() { if (milestone.trim()) { setValue({ ...value, milestones: [...value.milestones, { id: uid(), title: milestone.trim(), done: false }] }); setMilestone(''); } } return <Modal title={fresh ? 'A new direction' : 'Edit goal'} close={requestClose}><form className="editor-form" onSubmit={async event => { event.preventDefault(); if (!value.title.trim()) return; setBusy(true); const next = { ...value, title: value.title.trim(), milestones: milestone.trim() ? [...value.milestones, { id: uid(), title: milestone.trim(), done: false }] : value.milestones }; await save(next); setBusy(false); }}><label>Goal title<input autoFocus required value={value.title} onChange={event => setValue({ ...value, title: event.target.value })} placeholder="What do you want to achieve?" maxLength={200}/></label><label>Why it matters<textarea value={value.description} onChange={event => setValue({ ...value, description: event.target.value })} placeholder="Give this goal a little context…" rows={3}/></label><div className="form-two-columns"><label>Category<input value={value.category} onChange={event => setValue({ ...value, category: event.target.value })} placeholder="Personal"/></label><label>Target date<input type="date" value={value.due} onChange={event => setValue({ ...value, due: event.target.value })}/></label></div><div className="field-label">Milestones<span className="field-hint">Make progress tangible</span></div><div className="edit-milestones">{value.milestones.map((item, index) => <div key={item.id}><span className="milestone-number">{String(index + 1).padStart(2, '0')}</span><input aria-label={`Milestone ${index + 1}`} required value={item.title} onChange={event => setValue({ ...value, milestones: value.milestones.map(existing => existing.id === item.id ? { ...existing, title: event.target.value } : existing) })}/><IconButton label={`Remove milestone ${index + 1}`} onClick={() => setValue({ ...value, milestones: value.milestones.filter(existing => existing.id !== item.id) })}><X size={15}/></IconButton></div>)}</div><div className="add-milestone"><input aria-label="New milestone" value={milestone} onChange={event => setMilestone(event.target.value)} placeholder="Add a small, actionable step…" onKeyDown={event => { if (event.key === 'Enter') { event.preventDefault(); add(); } }}/><button type="button" className="button" onClick={add} disabled={!milestone.trim()}><Plus size={15}/>Add</button></div>{discard && <div className="inline-confirm"><span>You have unsaved changes.</span><button type="button" className="text-button danger-text" onClick={close}>Discard changes</button><button type="button" className="text-button" onClick={() => setDiscard(false)}>Keep editing</button></div>}<div className="modal-footer"><button type="button" className="button" onClick={requestClose}>Cancel</button><button className="button primary" disabled={busy || !value.title.trim()}>{busy && <Loader2 className="spin" size={15}/>} {fresh ? 'Create goal' : 'Save changes'}</button></div></form></Modal>; }

// Before a message goes to the provider, the brain index answers it locally (q.py through /api/brain, tens of
// milliseconds, no model call). A hit becomes one context doc so the model can say where things are instead
// of searching. No index, no match, or a hosted deploy: nothing is added and the message still goes.
type BrainReply = { status?: string; winner?: { path?: string; heading?: string; kind?: string; confidence?: string; ms?: number }; evidence?: string; ms?: number };
async function brainEvidence(question: string): Promise<{ name: string; content: string; kind: 'note'; ms: number }[]> {
  try {
    const reply = await api<BrainReply>('brain?q=' + encodeURIComponent(question));
    if (reply.status !== 'ok' || !reply.winner || !reply.evidence) return [];
    return [{ name: `Brain evidence: ${reply.winner.heading || reply.winner.path}`, content: `Source: ${reply.winner.path}\nSection: ${reply.winner.heading}\nConfidence: ${reply.winner.confidence}\n\n${reply.evidence}`, kind: 'note', ms: reply.ms || reply.winner.ms || 0 }];
  } catch { return []; }
}
function Chat({ workspace, commit, connections, liveContext, attached, setAttached, activeId, setActiveId, navigate, notify, confirm, installed, attachSkill, initialPrompt, clearInitialPrompt }: { workspace: Workspace; commit: Commit; connections: Connections | null; liveContext: Doc[]; attached: string[]; setAttached: (ids: string[] | ((ids: string[]) => string[])) => void; activeId: string | null; setActiveId: (id: string | null) => void; navigate: (page: Page) => void; notify: (text: string, error?: boolean) => void; confirm: (value: Confirm) => void; installed: InstalledSkill[]; attachSkill: (skill: InstalledSkill) => void; initialPrompt: string; clearInitialPrompt: () => void }) {
  const [provider, setProvider] = useState('claude'); const [model, setModel] = useState(connections?.models.claude || defaultModels.claude);
  const [useBrain, setUseBrain] = useState(true); const [lastEvidence, setLastEvidence] = useState<{ name: string; ms: number } | null>(null); const [customModel, setCustomModel] = useState(false);
  // A question typed on the home page lands here with the caret ready; the hand-off is one-shot.
  useEffect(() => { if (initialPrompt) { setPrompt(initialPrompt); clearInitialPrompt(); } }, [initialPrompt, clearInitialPrompt]);
  const knownModels = [...new Set([connections?.models[provider], defaultModels[provider], ...(knownModelIds[provider] || []), model].filter((m): m is string => Boolean(m)))]; const [prompt, setPrompt] = useState(''); const [busy, setBusy] = useState(false); const busyRef = useRef(false); const [error, setError] = useState(''); const [contextOpen, setContextOpen] = useState(false); const [contextQuery, setContextQuery] = useState(''); const [historyOpen, setHistoryOpen] = useState(false); const [rename, setRename] = useState<Conversation | null>(null); const end = useRef<HTMLDivElement>(null);
  const conversation = workspace.conversations.find(chat => chat.id === activeId); const attachedDocs = [...workspace.docs, ...liveContext].filter(doc => attached.includes(doc.id)); const connected = !!connections?.providers[provider];
  useEffect(() => { end.current?.scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth', block: 'nearest' }); }, [conversation?.messages.length, busy]);
  function changeProvider(next: string) { setProvider(next); setModel(connections?.models[next] || defaultModels[next]); setError(''); }
  // draft defaults to the box's text; the Claude composer passes its own text plus pasted cards and textual files as extra context.
  async function send(draft = prompt, extra: { name: string; content: string; kind: string }[] = []) { const text = draft.trim(); if (!text || !model.trim() || busyRef.current) return; busyRef.current = true; setBusy(true); setError(''); const id = conversation?.id || uid(); const userMessage = { id: uid(), role: 'user' as const, content: text, created: now(), provider, model }; const messages = [...(conversation?.messages || []), userMessage]; const chat: Conversation = { id, title: conversation?.title || text.slice(0, 65), messages, updated: now() };
    const saved = await commit(w => ({ ...w, conversations: w.conversations.some(item => item.id === id) ? w.conversations.map(item => item.id === id ? chat : item) : [chat, ...w.conversations] }));
    if (!saved) { busyRef.current = false; setBusy(false); return; } setActiveId(id); setPrompt('');
    const evidence = useBrain ? await brainEvidence(text) : []; setLastEvidence(evidence[0] ? { name: evidence[0].name, ms: evidence[0].ms } : null);
    try { const response = await api<{ text: string }>('chat', { provider, model: model.trim(), messages: messages.map(message => ({ role: message.role, content: message.content })), context: [...evidence.map(doc => ({ name: doc.name, content: doc.content, kind: doc.kind })), ...extra, ...attachedDocs.filter(isText).map(doc => ({ name: doc.name, content: doc.content, kind: doc.kind }))] }); if (!response.text) throw new Error('The provider returned an empty response.'); const assistant = { id: uid(), role: 'assistant' as const, content: response.text, created: now(), provider, model }; const stored = await commit(w => withActivity({ ...w, conversations: w.conversations.map(item => item.id === id ? { ...item, messages: [...item.messages, assistant], updated: now() } : item) }, `Conversation with ${providerNames[provider]}: ${chat.title}`, 'chat')); if (!stored) { download(`unsaved-response-${Date.now()}.txt`, new Blob([response.text], { type: 'text/plain' })); setError('The response could not be saved to browser storage. It has been downloaded as a text file.'); } } catch (error) { setError(error instanceof Error ? error.message : 'The provider could not complete this request.'); } finally { setBusy(false); busyRef.current = false; }
  }
  return <><PageHeading title="andliu.ai"><button className="button primary" disabled={busy} onClick={() => { setActiveId(null); setPrompt(''); setAttached([]); setError(''); }}><Plus size={16}/>New chat</button></PageHeading><div className="chat-workspace panel"><div className="chat-top"><div className="chat-session-title"><MessageSquare size={17}/><strong>{conversation?.title || 'A new conversation'}</strong>{conversation && <IconButton label="Rename conversation" onClick={() => setRename(conversation)}><Pencil size={13}/></IconButton>}</div><div className="chat-top-actions"><span className={`connection-tag ${connected ? 'online' : ''}`}><span className="status-dot"/>{connected ? `${providerNames[provider]} connected` : `${providerNames[provider]} not configured`}</span>
    <label className="chat-skill-pick"><span className="sr-only">Attach a skill</span><select aria-label="Attach a skill" value="" disabled={busy} onChange={event => { const skill = installed.find(item => item.slug === event.target.value); if (skill) attachSkill(skill); }}><option value="">Skill…</option>{installed.map(skill => <option key={skill.slug} value={skill.slug}>{skill.name}</option>)}</select></label>
    <label className="chat-brain-toggle" title="Look up your files and notes in the brain index before answering"><input type="checkbox" checked={useBrain} onChange={event => setUseBrain(event.target.checked)}/>Brain{lastEvidence && <small>{Math.round(lastEvidence.ms)} ms</small>}</label><button className="button small" onClick={() => setHistoryOpen(true)}><Clock3 size={14}/>History<span className="button-count">{workspace.conversations.length}</span></button></div></div><div className="chat-messages">{!conversation?.messages.length ? <div className="chat-welcome"><div className="chat-spark"><Sparkles size={30} strokeWidth={1.3}/></div><span className="eyebrow">THINK IT THROUGH, TOGETHER</span><h2>Where should we begin?</h2><p>A half-formed idea. A hard question. A plan that needs a plan.<br/>Bring it here, along with a little context.</p><div className="prompt-starters">{[{ icon: Layers3, title: 'Connect the dots', prompt: 'Help me connect the ideas in my attached notes. What patterns or useful connections do you see?' }, { icon: Target, title: 'Make a plan', prompt: 'Help me turn this idea into a clear, practical plan. Ask me a few questions to get started.' }, { icon: Pencil, title: 'Find the words', prompt: 'Help me develop a clear first draft. Ask about the audience, purpose, and tone before we begin.' }].map(({ icon: Icon, title, prompt }) => <button key={title} onClick={() => setPrompt(prompt)}><Icon size={18}/><strong>{title}</strong><ArrowUpRight size={14}/></button>)}</div></div> : conversation.messages.map(message => <div key={message.id} className={`message message-${message.role}`}><div className="message-avatar">{message.role === 'user' ? 'Y' : <Sparkles size={17}/>}</div><div className="message-body"><div className="message-byline"><strong>{message.role === 'user' ? 'You' : 'andliu.ai'}</strong><span>{message.role === 'assistant' ? message.model : new Date(message.created).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' })}</span></div><Markdown content={message.content}/></div></div>)}{busy && <div className="message"><div className="message-avatar"><Sparkles size={17}/></div><div className="thinking-indicator"><Loader2 size={15} className="spin"/>{providerNames[provider]} is thinking…</div></div>}<div ref={end}/></div>{error && <div className="chat-error error-banner" role="alert"><p>{error}</p><span>Your message is saved. No replacement response has been generated.</span></div>}<div className="chat-prompt-composer"><div className="attached-context">{attachedDocs.map(doc => <span className="context-chip" key={doc.id}>{doc.kind === 'skill' ? <Zap size={12}/> : <FileText size={12}/>}<span>{doc.name}</span><button aria-label={`Remove ${doc.name} from context`} onClick={() => setAttached(ids => ids.filter(id => id !== doc.id))}><X size={12}/></button></span>)}</div><Suspense fallback={<textarea className="cci-textarea" aria-label="Opening the composer" placeholder="Opening the composer…" disabled rows={3}/>}>{provider === 'claude'
      // Claude gets the Claude-style composer (files, big pastes as cards, a model menu); every other provider gets the default one below.
      ? <ClaudeChatInput aria-label="Message" placeholder="How can I help you today?" disabled={busy} submitDisabled={!connected || !model.trim()} models={knownModels.map(id => ({ id, name: id, description: providerNames[provider] }))} selectedModel={model} onModelChange={next => { setCustomModel(false); setModel(next); }}
        onSendMessage={(message, files, pasted) => void send(message.trim() || 'See the attached content.', [...pasted.map((p, i) => ({ name: `Pasted text ${i + 1}`, content: p.content, kind: 'note' })), ...files.filter(f => f.textContent).map(f => ({ name: f.file.name, content: f.textContent || '', kind: 'file' }))])}/>
      : <Compose value={prompt} onChange={setPrompt} onSubmit={() => void send()} placeholder="Ask andliu.ai. @ attaches a file or skill, / calls a skill" aria-label="Message" submitLabel="Send message" disabled={busy} submitDisabled={!connected || !model.trim()}
      mentions={[...workspace.docs.filter(isText).map(doc => ({ id: doc.id, label: doc.name, sublabel: doc.kind === 'skill' ? 'your skill' : doc.kind === 'note' ? 'note' : 'file' })), ...installed.map(skill => ({ id: 'installed:' + skill.slug, label: skill.name, sublabel: 'installed skill' }))]}
      commands={installed.map(skill => ({ id: skill.slug, label: skill.slug, hint: skill.description.slice(0, 70) }))}
      onMention={mention => { const skill = mention.id.startsWith('installed:') ? installed.find(item => 'installed:' + item.slug === mention.id) : undefined; if (skill) attachSkill(skill); else setAttached(ids => ids.includes(mention.id) ? ids : [...ids, mention.id]); }}
      onCommand={command => { const skill = installed.find(item => item.slug === command.id); if (skill) attachSkill(skill); }}/>}</Suspense><div className="composer-controls"><div className="composer-left"><button className="button small context-button" onClick={() => setContextOpen(true)}><Paperclip size={14}/>Add context</button><label className="provider-select"><span className="sr-only">Chat provider</span><select value={provider} disabled={busy} onChange={event => changeProvider(event.target.value)}>{['claude', 'openai', 'gemini'].map(item => <option key={item} value={item}>{providerNames[item]}</option>)}</select></label><label className="model-input"><span className="sr-only">Model</span><select aria-label="Chat model" value={customModel ? 'custom' : model} disabled={busy} onChange={event => { if (event.target.value === 'custom') setCustomModel(true); else { setCustomModel(false); setModel(event.target.value); } }}>{knownModels.map(item => <option key={item} value={item}>{item}</option>)}<option value="custom">Other model…</option></select></label>{customModel && <label className="model-input"><span className="sr-only">Model ID</span><input aria-label="Chat model ID" title="Editable model ID" value={model} disabled={busy} onChange={event => setModel(event.target.value)}/></label>}</div><a className="text-button" href="/prompt-demo">Input demo</a></div></div><div className="chat-disclaimer">{connected ? <><ShieldCheck size={12}/>Only the files and skills you attach are sent as context. Provider usage may incur charges.</> : <><span>Connect a provider to start the conversation.</span><button className="text-button" onClick={() => navigate('settings')}>Open settings <ArrowUpRight size={12}/></button></>}</div></div>
    {contextOpen && <Modal title="Give the conversation some context" close={() => setContextOpen(false)}><div className="source-intro"><p>Select saved files or skills. Their text will be sent to your chosen AI provider with your messages.</p><label className="inline-search"><Search size={15}/><input autoFocus aria-label="Search context" value={contextQuery} onChange={event => setContextQuery(event.target.value)} placeholder="Search files and skills…"/></label></div><div className="context-list">{workspace.docs.filter(doc => `${doc.name} ${doc.tags.join(' ')}`.toLowerCase().includes(contextQuery.toLowerCase())).map(doc => <label className={`context-option ${!isText(doc) ? 'unavailable' : ''}`} key={doc.id}><input type="checkbox" disabled={!isText(doc)} checked={attached.includes(doc.id)} onChange={event => setAttached(ids => event.target.checked ? [...ids, doc.id] : ids.filter(id => id !== doc.id))}/><span className={`doc-symbol ${doc.kind}`}>{doc.kind === 'skill' ? <Zap size={17}/> : <FileText size={17}/>}</span><span><strong>{doc.name}</strong><small>{isText(doc) ? `${doc.kind} · ${doc.content.length.toLocaleString()} characters` : 'Binary file · text context unavailable'}</small></span></label>)}</div><div className="modal-footer"><span className="muted">{attachedDocs.length} attached</span><button className="button primary" onClick={() => setContextOpen(false)}>Done <Check size={15}/></button></div></Modal>}
    {historyOpen && <Modal title="Your conversations" close={() => setHistoryOpen(false)}><div className="conversation-history">{workspace.conversations.length ? workspace.conversations.map(chat => <div className="history-item" key={chat.id}><button disabled={busy} onClick={() => { setActiveId(chat.id); setHistoryOpen(false); setError(''); }}><MessageSquare size={17}/><span><strong>{chat.title}</strong><small>{chat.messages.length} messages · {formatDate(chat.updated)}</small></span></button><IconButton label={`Delete ${chat.title}`} disabled={busy} onClick={() => { setHistoryOpen(false); confirm({ title: 'Delete conversation?', description: `“${chat.title}” and all its messages will be removed from this browser.`, danger: true, label: 'Delete conversation', action: async () => { if (await commit(w => ({ ...w, conversations: w.conversations.filter(item => item.id !== chat.id) }), 'Conversation deleted')) { if (activeId === chat.id) setActiveId(null); } } }); }}><Trash2 size={15}/></IconButton></div>) : <Empty icon={MessageSquare} title="Your conversations will live here">Start a conversation to build a history you can return to.</Empty>}</div></Modal>}
    {rename && <Modal title="Rename conversation" close={() => setRename(null)}><form className="editor-form" onSubmit={async event => { event.preventDefault(); if (await commit(w => ({ ...w, conversations: w.conversations.map(chat => chat.id === rename.id ? { ...chat, title: rename.title.trim() } : chat) }), 'Conversation renamed')) setRename(null); }}><label>Conversation name<input autoFocus value={rename.title} onChange={event => setRename({ ...rename, title: event.target.value })} required maxLength={200}/></label><div className="modal-footer"><button type="button" className="button" onClick={() => setRename(null)}>Cancel</button><button className="button primary" disabled={!rename.title.trim()}>Save name</button></div></form></Modal>}
  </>;
}

function Generate({ workspace, commit, connections, navigate, notify, confirm }: { workspace: Workspace; commit: Commit; connections: Connections | null; navigate: (page: Page) => void; notify: (text: string, error?: boolean) => void; confirm: (value: Confirm) => void }) {
  const [provider, setProvider] = useState('gemini'); const [prompt, setPrompt] = useState(''); const [aspect, setAspect] = useState('1:1'); const [busy, setBusy] = useState(false); const busyRef = useRef(false); const [checking, setChecking] = useState<string[]>([]); const [error, setError] = useState(''); const [selected, setSelected] = useState<Generation | null>(null);
  const connected = !!connections?.providers[provider];
  const [recovery, setRecovery] = useState<Workspace | null>(null);
  function offerRecovery(data: Workspace) { setRecovery(data); setError('The provider returned a result, but browser storage could not save it. A recovery backup download was requested. Use Download recovery backup below and restore it in Settings. Do not pay for another run.'); download('second-brain-backup-recovery-' + Date.now() + '.json', new Blob([JSON.stringify(data)], {type:'application/json'})); }
  async function generate() { if (!prompt.trim() || busyRef.current) return; busyRef.current = true; setBusy(true); setError(''); const generation: Generation = { id: uid(), prompt: prompt.trim(), provider, model: connections?.models[provider === 'gemini' ? 'geminiImage' : provider] || ({gemini:'gemini-3.1-flash-image',fal:'fal-ai/flux/schnell',kie:'nano-banana-pro'} as Record<string,string>)[provider], aspect, status: 'queued', images: [], created: now() }; if (!await commit(w => ({ ...w, generations: [generation, ...w.generations] }))) { setBusy(false); busyRef.current = false; return; }
    try { const response = await api<{ job?: string; images: string[]; model: string; status: 'queued' | 'complete' }>('generate', { provider, prompt: generation.prompt, aspect }); let recoverable = workspace; const stored = await commit(w => { recoverable = withActivity({ ...w, generations: w.generations.map(item => item.id === generation.id ? { ...item, ...response } : item) }, response.status === 'complete' ? 'Created an image' : 'Started an image generation', 'generate'); return recoverable; }, response.status === 'complete' ? 'Your image is ready' : 'Generation queued. Check its status to retrieve the result.'); if (!stored) offerRecovery(recoverable); else if (response.status === 'complete') setPrompt(''); } catch (error) { const message = error instanceof Error ? error.message : 'Generation request failed'; setError(message); await commit(w => ({ ...w, generations: w.generations.map(item => item.id === generation.id ? { ...item, status: 'failed', error: message } : item) })); } finally { busyRef.current = false; setBusy(false); }
  }
  async function resume(item: Generation) { if (!item.job || checking.includes(item.id)) return; setChecking(ids => [...ids, item.id]); try { const response = await api<{ job?: string; images: string[]; model: string; status: 'queued' | 'complete' }>('generation-status', { provider: item.provider, job: item.job }); let recoverable = workspace; const stored = await commit(w => { recoverable = { ...w, generations: w.generations.map(existing => existing.id === item.id ? { ...existing, ...response } : existing) }; return recoverable; }, response.status === 'complete' ? 'Your image is ready' : 'Still processing. Check again shortly.'); if (!stored) offerRecovery(recoverable); } catch (error) { notify(error instanceof Error ? error.message : 'Could not check generation', true); } finally { setChecking(ids => ids.filter(id => id !== item.id)); } }
  async function saveImage(item: Generation) { const data = item.images[0]; if (!data) return; const mime = /^data:([^;]+);/.exec(data)?.[1] || 'image/png'; const extension = mime === 'image/jpeg' ? 'jpg' : mime.split('/')[1] || 'png'; const doc: Doc = { ...makeDoc(`Generated image ${formatDate(item.created)}.${extension}`, item.prompt, 'file', ['Generated']), data, mime }; await commit(w => withActivity({ ...w, docs: [doc, ...w.docs] }, 'Saved generated image to Files', 'files'), 'Image added to Files'); }
  return <><PageHeading title="Generate"/><div className="generate-layout"><section className="panel generation-composer"><div className="section-heading"><h2><WandSparkles size={17}/>Create an image</h2><span className="tag">STUDIO</span></div><label>What do you imagine?<textarea value={prompt} onChange={event => setPrompt(event.target.value)} placeholder="A quiet reading room at dusk. Warm copper light, shelves of well-loved books, a notebook left open…" rows={7}/></label><div className="prompt-guidance"><Sparkles size={13}/>A subject, a mood, a few details. Start there.</div><label>Provider<select value={provider} disabled={busy} onChange={event => { setProvider(event.target.value); setError(''); }}>{['gemini', 'kie', 'fal'].map(item => <option value={item} key={item}>{providerNames[item]}</option>)}</select></label><div className="field-label">Aspect ratio</div><div className="aspect-options">{['1:1', '16:9', '9:16', '4:3'].map(value => <button key={value} aria-pressed={aspect === value} className={aspect === value ? 'selected' : ''} onClick={() => setAspect(value)}><span style={{ aspectRatio: value.replace(':', ' / '), width: value === '9:16' ? 12 : 21 }}/>{value}</button>)}</div><div className="generation-model"><span>OUTPUT</span><strong>1 image per run</strong><span>{connections?.models[provider === 'gemini' ? 'geminiImage' : provider] || 'Connect to see model'}</span></div><button className="button primary generate-button" disabled={busy || !prompt.trim() || !connected} onClick={() => void generate()}>{busy ? <Loader2 className="spin" size={17}/> : <WandSparkles size={17}/>} {busy ? 'Creating your image…' : 'Generate image'}<ArrowUpRight size={16}/></button><p className="generation-cost">{connected ? 'Runs with your provider API key. Provider usage may incur charges.' : <><span>{providerNames[provider]} is not configured.</span> <button className="text-button" onClick={() => navigate('settings')}>Connect in Settings <ArrowUpRight size={12}/></button></>}</p>{error && <div className="error-banner" role="alert">{error}</div>}{recovery && <button className="button" onClick={() => download("second-brain-backup-recovery.json", new Blob([JSON.stringify(recovery)], {type:"application/json"}))}><Download size={15}/>Download recovery backup</button>}</section><section className="generation-gallery"><div className="gallery-heading"><h2>Your creations</h2><span className="muted">Saved in this browser</span></div>{workspace.generations.length ? <div className="image-grid">{workspace.generations.map(item => <article className="generation-card" key={item.id}>{item.status === 'complete' && item.images[0] ? <button className="generation-image-button" onClick={() => setSelected(item)}><img src={item.images[0]} alt={item.prompt} loading="lazy"/><span><ArrowUpRight size={17}/>View creation</span></button> : <div className={`generation-placeholder ${item.status === 'failed' ? 'failed' : ''}`}><span className="empty-icon">{item.status === 'failed' ? <ImagePlus size={24}/> : <Clock3 size={24}/>}</span><h3>{item.status === 'failed' ? 'Generation could not finish' : item.job ? 'A little imagination in progress.' : busy ? 'Sending to your provider…' : 'No job reference was saved'}</h3><p>{item.error || (item.job ? 'Your job is saved. You can return and retrieve the result.' : 'The request may have been interrupted. Check your provider before starting another run.')}</p>{item.job && item.status !== 'failed' && <button className="button small" onClick={() => void resume(item)} disabled={checking.includes(item.id)}>{checking.includes(item.id) ? <Loader2 size={14} className="spin"/> : <RefreshCw size={14}/>}Check status</button>}</div>}<div className="generation-card-info"><p>{item.prompt}</p><div><span>{providerNames[item.provider]} · {item.aspect}</span><IconButton label="Delete generation from workspace" disabled={busy && item.status === 'queued'} onClick={() => confirm({ title: 'Remove this generation?', description: 'This removes the image or saved job from this browser. It does not cancel a running provider job.', danger: true, label: 'Remove generation', action: () => commit(w => ({ ...w, generations: w.generations.filter(existing => existing.id !== item.id) }), 'Generation removed') })}><Trash2 size={14}/></IconButton></div></div></article>)}</div> : <div className="generation-empty"><div className="empty-art" aria-hidden="true"><div className="art-frame frame-back"/><div className="art-frame frame-middle"/><div className="art-frame frame-front"><div className="art-sun"/><div className="art-mountain one"/><div className="art-mountain two"/><Sparkles size={24}/></div><span className="art-twinkle"><Plus size={16}/></span></div><span className="eyebrow">AN OPEN CANVAS</span><h2>Every image starts<br/>with an idea.</h2><p>Describe what you have in mind.<br/>Your creations will find a home here.</p><div className="empty-provider-pills"><span>Gemini</span><span>Kie.ai</span><span>fal.ai</span></div></div>}</section></div>{selected && <Modal title="Your creation" close={() => setSelected(null)} wide><div className="creation-detail"><img src={selected.images[0]} alt={selected.prompt}/><p>{selected.prompt}</p><span className="muted">{providerNames[selected.provider]} · {selected.model} · {selected.aspect} · {formatDate(selected.created)}</span></div><div className="modal-footer"><button className="button" onClick={() => download("second-brain-generation-" + selected.id + ".json", new Blob([JSON.stringify({prompt:selected.prompt,model:selected.model,provider:selected.provider,aspect:selected.aspect,created:selected.created},null,2)],{type:"application/json"}))}><Download size={15}/>Metadata</button><button className="button" onClick={() => void saveImage(selected)}><Folder size={15}/>Save to Files</button><button className="button primary" onClick={() => download(`second-brain-${selected.id}.${selected.images[0].startsWith('data:image/jpeg') ? 'jpg' : 'png'}`, selected.images[0])}><Download size={15}/>Download image</button></div></Modal>}</>;
}

function Settings({ workspace, commit, connections, error, checking, refresh, confirm, notify }: { workspace: Workspace; commit: Commit; connections: Connections | null; error: string; checking: boolean; refresh: () => Promise<void>; confirm: (value: Confirm) => void; notify: (text: string, error?: boolean) => void }) {
  const [token, setToken] = useState(''); const backupRef = useRef<HTMLInputElement>(null); const [importing, setImporting] = useState(false);
  function exportBackup() { download(`second-brain-backup-${new Date().toISOString().slice(0, 10)}.json`, new Blob([JSON.stringify(workspace, null, 2)], { type: 'application/json' })); notify('Backup downloaded, including original file bytes'); }
  async function importBackup(file: File | undefined) { if (!file) return; setImporting(true); try { if (file.size > 260 * 1024 * 1024) throw new Error('This backup exceeds the 260 MB import limit.'); const data = parseBackup(await file.text()); confirm({ title: 'Replace your workspace from this backup?', description: `Validated backup: ${data.docs.length} files and skills, ${data.goals.length} goals, ${data.conversations.length} conversations, and ${data.generations.length} generations. This replaces the current browser workspace. Export your current data first if you want to keep it.`, label: 'Restore backup', action: () => commit(() => data, 'Workspace restored from backup') }); } catch (error) { notify(`Backup was not imported: ${error instanceof Error ? error.message : 'Invalid file'}`, true); } finally { setImporting(false); if (backupRef.current) backupRef.current.value = ''; } }
  return <><PageHeading title="Settings"><button className="button" onClick={() => void refresh()} disabled={checking}><RefreshCw size={15} className={checking ? 'spin' : ''}/>{checking ? 'Checking…' : 'Refresh connections'}</button></PageHeading><div className="settings-layout"><div className="settings-main"><section className="panel settings-section"><div className="section-heading"><h2><Sun size={17}/>Appearance</h2></div><p className="settings-intro">Light, dark, or whatever this computer is set to. The sun and moon in the top bar switch it in one click; this browser remembers the choice.</p><ThemeChoice/></section><section className="panel settings-section"><div className="section-heading"><h2><Zap size={17}/>AI connections</h2><span className={`connection-tag ${connections ? 'online' : ''}`}><span className="status-dot"/>{connections ? 'Server connected' : 'Server unavailable'}</span></div><p className="settings-intro">Connect your preferred intelligence. API keys stay on the server and are never saved in this browser.</p>{error && <div className="error-banner" role="alert">{error}</div>}<div className="provider-grid">{['claude', 'openai', 'gemini', 'kie', 'fal'].map((provider, i) => <div className="provider-card" key={provider}><span className={`provider-monogram provider-${provider}`}>{['C', 'O', 'G', 'K', 'f'][i]}</span><div><strong>{providerNames[provider]}</strong><small>{provider === 'gemini' ? 'Chat & image generation' : provider === 'kie' || provider === 'fal' ? 'Image generation' : 'Chat & reasoning'}</small></div><span className={`provider-state ${connections?.providers[provider] ? 'online' : ''}`}>{connections?.providers[provider] ? <><Check size={12}/>Connected</> : 'Not configured'}</span></div>)}</div><details className="setup-details"><summary><Code2 size={15}/>How to connect providers<ChevronDown size={15}/></summary><p>Add the keys you want to use to your server environment, then restart the server and refresh connections. For local development, copy <code>.env.example</code> to <code>.env</code>. For hosting, use your platform’s environment settings.</p><div className="environment-keys"><code>ANTHROPIC_API_KEY</code><code>OPENAI_API_KEY</code><code>GEMINI_API_KEY</code><code>KIE_API_KEY</code><code>FAL_KEY</code></div><p>Chat model IDs are editable in Chat. Image models are configured on the server. Read the project README for setup and supported providers.</p></details></section><section className="panel settings-section"><div className="section-heading"><h2><FolderOpen size={17}/>Local source library</h2><span className={`connection-tag ${connections?.local ? 'online' : ''}`}><span className="status-dot"/>{connections?.local ? 'Connected' : 'Not connected'}</span></div><div className="settings-info-row"><div className="settings-feature-icon"><HardDrive size={26}/></div><div><h3>Bring your existing work into focus.</h3><p>The local server can read configured project folders and installed Claude skills. Browse folders from Files and save personal copies; installed skills open straight from Skills, with nothing to copy.</p></div></div><details className="setup-details"><summary><Code2 size={15}/>Local library setup<ChevronDown size={15}/></summary><p>Run this project locally with <code>npm run dev</code>. Configure the source folder variables in <code>.env.example</code> to point to the documents you want to make available. Remote hosting cannot read folders on your computer.</p><p>Source files are read only. Edits to imported copies stay in your browser workspace.</p></details></section><section className="panel settings-section"><div className="section-heading"><h2><Database size={17}/>Your data</h2><span className="tag">LOCAL STORAGE</span></div><p className="settings-intro">Notes, original file bytes, skills, goals, conversations, and images are saved in this browser using IndexedDB. Clearing site data will remove them.</p><div className="data-actions"><div><div><h3>Take your workspace with you.</h3><p>Download a complete JSON backup, including imported files and generated images.</p></div><button className="button" onClick={exportBackup}><Download size={15}/>Export backup</button></div><div><div><h3>Restore a saved workspace.</h3><p>Import a validated Second Brain backup. You will review the contents before replacing your data.</p></div><button className="button" disabled={importing} onClick={() => backupRef.current?.click()}>{importing ? <Loader2 className="spin" size={15}/> : <Upload size={15}/>}Import backup</button></div></div><input ref={backupRef} className="sr-only" aria-label="Import workspace backup" type="file" accept=".json,application/json" onChange={event => void importBackup(event.target.files?.[0])}/></section>{connections?.authRequired && <section className="panel settings-section"><div className="section-heading"><h2><ShieldCheck size={17}/>Server access</h2></div><p className="settings-intro">This server requires an access token. It stays in memory for this tab and is cleared when you reload.</p><form className="token-form" onSubmit={async event => { event.preventDefault(); setAccessToken(token); setToken(''); await refresh(); }}><label>Access token<input type="password" autoComplete="off" value={token} onChange={event => setToken(event.target.value)} placeholder="Enter server access token"/></label><button className="button primary" disabled={!token.trim()}>Connect</button></form></section>}</div><aside className="settings-aside"><div className="privacy-card"><div className="privacy-emblem"><ShieldCheck size={32} strokeWidth={1.3}/></div><span className="eyebrow">PERSONAL BY DESIGN</span><h2>A space that's<br/>only yours.</h2><p>Your workspace lives on this device. Your API keys live on your server. You choose what becomes AI context.</p><div className="privacy-item"><Check size={14}/><span>No account required</span></div><div className="privacy-item"><Check size={14}/><span>Full backup and restore</span></div><div className="privacy-item"><Check size={14}/><span>You choose what to share</span></div><div className="sync-note"><span className="tag">LOOKING AHEAD</span><p>Cross-device sync is a future step. For now, export a backup to move your workspace between browsers or devices.</p></div></div><div className="settings-fact"><Brain size={20}/><div><strong>Second Brain</strong><span>A little less scattered.</span><small>Version 1.0 · Personal workspace</small></div></div></aside></div>{!connections && <section className="panel settings-section fallback-token"><h3>Using a protected server?</h3><p className="muted">If your server uses an access token, enter it here to reconnect.</p><form className="token-form" onSubmit={async event => { event.preventDefault(); setAccessToken(token); setToken(''); await refresh(); }}><label>Access token<input type="password" autoComplete="off" value={token} onChange={event => setToken(event.target.value)} placeholder="Server access token"/></label><button className="button primary" disabled={!token.trim()}>Connect</button></form></section>}</>;
}
